// Record one heartbeat. Body: {"job": "nightly-export", "interval_minutes": 60}
const body = $input.first().json.body || {};
const job = String(body.job || '').trim().slice(0, 100);
const interval = Number(body.interval_minutes);
if (!job || !Number.isFinite(interval) || interval <= 0 || interval > 10080) {
  return [{ json: { ok: false, error: 'Send {"job": "<name>", "interval_minutes": <1-10080>}' } }];
}
const data = $getWorkflowStaticData('global');
data.jobs = data.jobs || {};
const previous = data.jobs[job] || {};
const recovered = previous.state === 'late' || previous.state === 'down';
data.jobs[job] = { last: Date.now(), interval, state: 'ok' };
return [{ json: { ok: true, job, interval_minutes: interval, recovered, previous_state: previous.state || null, received_at: new Date().toISOString() } }];

// A heartbeat that arrives after a late or down state is reported once as a recovery.
const item = $input.first().json;
if (!item.recovered) return [];
return [{ json: { job: item.job, state: 'ok', previous_state: item.previous_state, message: `${item.job} is back to normal: heartbeat received at ${item.received_at}` } }];

// Runs every minute. A job is late after 1.5x its interval and down after 2x,
// strict comparisons, like the Datvero heartbeat detection envelope.
const LATE = 1.5, DOWN = 2;
const data = $getWorkflowStaticData('global');
const jobs = data.jobs || {};
const now = Date.now();
const out = [];
for (const [job, j] of Object.entries(jobs)) {
  const elapsedMin = (now - j.last) / 60000;
  const state = elapsedMin > j.interval * DOWN ? 'down' : elapsedMin > j.interval * LATE ? 'late' : 'ok';
  if (state !== j.state && state !== 'ok') {
    out.push({ json: { job, state, previous_state: j.state, elapsed_minutes: Math.round(elapsedMin * 10) / 10,
      interval_minutes: j.interval, last_heartbeat: new Date(j.last).toISOString(),
      message: `${job} is ${state}: no heartbeat for ${Math.round(elapsedMin)} min (expected every ${j.interval} min)` } });
  }
  j.state = state;
}
return out;
